args.command:
cat << 'EOF' > /app/test_eval3.py
import pandas as pd
import json

with open('/app/dataset/sensors_calibration.json', 'r') as f:
    calib = json.load(f)['enterprise_platform']['deployment_environments']['system_config']['farms']

for farm_id in calib:
    file_path = f"/app/dataset/production_{farm_id}.csv"
    try:
        with open(file_path, "r", encoding="utf-16") as f:
            for _ in range(3): f.readline()
            header = f.readline()
        encoding = "utf-16"
    except:
        with open(file_path, "r", encoding="utf-8") as f:
            for _ in range(3): f.readline()
            header = f.readline()
        encoding = "utf-8"

    sep = ";" if ";" in header else ","
    df = pd.read_csv(file_path, encoding=encoding, skiprows=3, sep=sep, dtype=str)

    val_col_name = calib[farm_id]['calibration_data']['value_column_name']
    s = df[val_col_name].astype(str)

    try:
        if sep == ';':
            s = s.str.replace('.', '', regex=False).str.replace(',', '.', regex=False)
        else:
            s = s.str.replace(',', '', regex=False)
    except Exception as e:
        print(f"Error in {farm_id} for col '{val_col_name}': {type(s)} {e}")
EOF
python3 /app/test_eval3.py

