args.command:
python3 -c "
import pandas as pd, json
calib = json.load(open('/app/dataset/sensors_calibration.json'))['enterprise_platform']['deployment_environments']['system_config']['farms']
for farm_id in calib:
    try: df = pd.read_csv(f'/app/dataset/production_{farm_id}.csv', encoding='utf-16', skiprows=3, sep=None, engine='python')
    except: df = pd.read_csv(f'/app/dataset/production_{farm_id}.csv', encoding='utf-8', skiprows=3, sep=None, engine='python')
    d1 = len(df) - len(df.drop_duplicates())
    d2 = len(df) - len(df.drop_duplicates(subset=[df.columns[0]]))
    if d1 > 0 or d2 > 0:
        print(f'{farm_id} - Exact: {d1}, Subset(timestamp): {d2}')
"

